function getTime(countDownDate){let now=(new Date).getTime(),distance=countDownDate-now;return{now:now,distance:distance,days:Math.floor(distance/864e5),hours:Math.floor(distance%864e5/36e5),minutes:Math.floor(distance%36e5/6e4),seconds:Math.floor(distance%6e4/1e3)}}function setTime($count,{days:days,hours:hours,minutes:minutes}){$count.find(".days").text(days),$count.find(".hours").text(hours),$count.find(".hours").text(minutes)}$("[data-countdown]").length&&$("[data-countdown]").each((index,_count)=>{let $count=$(_count),data=$count.data(),countDownDate=new Date(data.countdown).getTime(),init_times=getTime(countDownDate);setTime($count,init_times);let timer=setInterval(()=>{let times=getTime(countDownDate);setTime($count,times),times.distance<0&&(clearInterval(timer),$count.find(".days , .hours  , .hours").text("00"))},6e4)});